cd /tmp && php -r '
$pdo = new PDO("pgsql:host=postgres;port=5432;dbname=llmapi_eval","eval_rw","eval_rw",[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
foreach (["author","book","customer","purchase","purchase_line"] as $t) {
 echo "== $t\n";
 foreach ($pdo->query("select column_name,data_type,is_nullable,column_default from information_schema.columns where table_schema=current_schema() and table_name='$t' order by ordinal_position") as $r) echo implode(" | ", $r), "\n";
 echo "rows: ", $pdo->query("select count(*) from $t")->fetchColumn(), "\n";
}
foreach ($pdo->query("select conrelid::regclass, pg_get_constraintdef(oid) from pg_constraint where connamespace=current_schema()::regnamespace") as $r) echo implode(" | ",$r),"\n";
'

cd /tmp && php -r '
$pdo = new PDO("pgsql:host=postgres;port=5432;dbname=llmapi_eval","eval_rw","eval_rw",[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
foreach (["author","book","customer","purchase","purchase_line"] as $t) {
 echo "== $t\n";
 $s=$pdo->prepare("select column_name,data_type,is_nullable,column_default from information_schema.columns where table_schema=current_schema() and table_name=? order by ordinal_position"); $s->execute([$t]);
 foreach ($s as $r) echo implode(" | ", $r), "\n";
 echo "rows: ", $pdo->query("select count(*) from $t")->fetchColumn(), "\n";
}
foreach ($pdo->query("select conrelid::regclass, pg_get_constraintdef(oid) from pg_constraint where connnamespace=current_schema()::regnamespace") as $r) echo implode(" | ",$r),"\n";
'

cd /tmp && php -r '
$pdo = new PDO("pgsql:host=postgres;port=5432;dbname=llmapi_eval","eval_rw","eval_rw",[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
foreach (["select * from author order by id","select id,title,author_id,published,price_cents,published_at,stock from book order by id","select * from customer order by id","select * from purchase order by id","select * from purchase_line order by id","select conname, pg_get_constraintdef(oid) from pg_constraint where connamespace=current_schema()::regnamespace","select tablename from pg_tables where schemaname=current_schema()"] as $q) { echo "-- $q\n"; foreach ($pdo->query($q) as $r) echo json_encode($r), "\n"; }
'

